#!/usr/bin/env python3
import sys
import os

if len(sys.argv) < 2:
    print("Usage: extract_token.py <pid>", file=sys.stderr)
    sys.exit(1)

pid = sys.argv[1]

try:
    with open(f'/proc/{pid}/maps', 'r') as maps_f:
        for line in maps_f:
            parts = line.split()
            if len(parts) < 5:
                continue
            addr_range = parts[0]
            perms = parts[1]

            if 'r' not in perms:
