            start, end = addr_range.split('-')
            start = int(start, 16)
            end = int(end, 16)
            size = end - start

            if size > 100 * 1024 * 1024:
                continue

            try:
                with open(f'/proc/{pid}/mem', 'rb') as mem_f:
                    mem_f.seek(start)
                    data = mem_f.read(min(size, 5*1024*1024))

                    # Search for token
                    if b'THESISKEY{' in data:
                        idx = data.find(b'THESISKEY{')
                        end_idx = data.find(b'}', idx)
                        if end_idx != -1:
                            token = data[idx:end_idx+1].decode('utf-8', errors='ignore')
                            print(f"{token}")
                            sys.exit(0)
            except Exception as e:
                pass
except Exception as e:
    print(f"Error: {e}", file=sys.stderr)

sys.exit(1)
